// Classe BASE: representa qualquer mídia do acervo.
export class Midia {
  constructor(titulo, ano) {
    if (typeof titulo !== 'string' || titulo.trim() === '') {
      throw new Error('titulo precisa ser um texto não vazio');
    }
    if (typeof ano !== 'number') {
      throw new Error('ano precisa ser um número');
    }
    this.titulo = titulo;
    this.ano = ano;
  }

  descricao() {
    return `Mídia: ${this.titulo} (${this.ano})`;
  }

  diasDeEmprestimo() {
    return 7; // mídia comum: 7 dias
  }
}

// Livro É UMA Mídia: herda título/ano e acrescenta autor e páginas.
export class Livro extends Midia {
  constructor(titulo, ano, autor, paginas) {
    super(titulo, ano); // a mãe valida e guarda titulo/ano
    if (typeof autor !== 'string' || autor.trim() === '') {
      throw new Error('autor precisa ser um texto não vazio');
    }
    if (typeof paginas !== 'number' || paginas < 1) {
      throw new Error('paginas precisa ser um número maior ou igual a 1');
    }
    this.autor = autor;
    this.paginas = paginas;
  }

  descricao() {
    return `Livro: ${this.titulo} (${this.ano}) — ${this.autor}, ${this.paginas} páginas`;
  }

  diasDeEmprestimo() {
    return 14; // livro: 14 dias
  }
}

// DVD É UMA Mídia: herda título/ano e acrescenta diretor e duração.
export class DVD extends Midia {
  constructor(titulo, ano, diretor, duracaoMin) {
    super(titulo, ano);
    if (typeof diretor !== 'string' || diretor.trim() === '') {
      throw new Error('diretor precisa ser um texto não vazio');
    }
    if (typeof duracaoMin !== 'number' || duracaoMin < 1) {
      throw new Error('duracaoMin precisa ser um número maior ou igual a 1');
    }
    this.diretor = diretor;
    this.duracaoMin = duracaoMin;
  }

  descricao() {
    return `DVD: ${this.titulo} (${this.ano}) — ${this.diretor}, ${this.duracaoMin} min`;
  }

  diasDeEmprestimo() {
    return 3; // DVD: 3 dias
  }
}

