import { Midia } from './classes.mjs';

// A Biblioteca TEM mídias (composição) e controla os empréstimos.
// Ela conversa com as mídias apenas pelos métodos públicos de Midia —
// o polimorfismo garante que cada tipo responda certo para descricao()
// e diasDeEmprestimo(), sem nenhum if por tipo aqui dentro.
export class Biblioteca {
  #acervo = [];             // composição: a biblioteca TEM uma lista de mídias
  #emprestadas = {};        // títulos fora da prateleira (chave = título)

  // Porteiro do acervo: só entra objeto da família Midia.
  adicionarMidia(midia) {
    if (!(midia instanceof Midia)) {
      throw new Error('só aceita mídias do tipo Midia (ou subclasse)');
    }
    this.#acervo.push(midia);
  }

  // Polimorfismo em ação: o prazo vem do tipo real da mídia (14/3/7).
  emprestar(titulo) {
    const midia = this.#acervo.find((m) => m.titulo === titulo);
    if (!midia) {
      throw new Error(`mídia "${titulo}" não encontrada no acervo`);
    }
    if (this.#emprestadas[titulo] === true) {
      throw new Error(`mídia "${titulo}" já está emprestada`);
    }
    this.#emprestadas[titulo] = true;
    return midia.diasDeEmprestimo();
  }

  devolver(titulo) {
    if (this.#emprestadas[titulo] !== true) {
      throw new Error(`mídia "${titulo}" não está emprestada`);
    }
    this.#emprestadas[titulo] = undefined;
  }

  // Mantém a ordem do acervo: filtra e converte em descrições.
  disponiveis() {
    const resultado = [];
    for (const m of this.#acervo) {
      if (this.#emprestadas[m.titulo] !== true) {
        resultado.push(m.descricao());
      }
    }
    return resultado;
  }

  emprestadas() {
    const resultado = [];
    for (const m of this.#acervo) {
      if (this.#emprestadas[m.titulo] === true) {
        resultado.push(m.descricao());
      }
    }
    return resultado;
  }
}

