import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Midia, Livro, DVD } from './lib/classes.mjs';
import { Biblioteca } from './lib/servico.mjs';

test('herança: livro e DVD são mídias, com campos próprios', () => {
  const livro = new Livro('O Cortiço', 1890, 'Aluísio Azevedo', 320);
  const dvd = new DVD('Matrix', 1999, 'Lana Wachowski', 136);
  assert.equal(livro instanceof Midia, true);
  assert.equal(dvd instanceof Midia, true);
  assert.equal(livro instanceof Livro, true);
  assert.equal(livro.autor, 'Aluísio Azevedo');
  assert.equal(dvd.diretor, 'Lana Wachowski');
});

test('polimorfismo: mesmo método descricao(), comportamentos diferentes', () => {
  const midia = new Midia('Álbum X', 2020);
  const livro = new Livro('O Cortiço', 1890, 'Aluísio Azevedo', 320);
  const dvd = new DVD('Matrix', 1999, 'Lana Wachowski', 136);
  assert.equal(midia.descricao(), 'Mídia: Álbum X (2020)');
  assert.equal(livro.descricao(), 'Livro: O Cortiço (1890) — Aluísio Azevedo, 320 páginas');
  assert.equal(dvd.descricao(), 'DVD: Matrix (1999) — Lana Wachowski, 136 min');
});

test('polimorfismo no serviço: o prazo de empréstimo depende do tipo', () => {
  const biblioteca = new Biblioteca();
  biblioteca.adicionarMidia(new Livro('Dom Casmurro', 1899, 'Machado de Assis', 256));
  biblioteca.adicionarMidia(new DVD('Titanic', 1997, 'James Cameron', 195));
  biblioteca.adicionarMidia(new Midia('Disco Vinil', 1980));
  assert.equal(biblioteca.emprestar('Dom Casmurro'), 14); // livro: 14 dias
  assert.equal(biblioteca.emprestar('Titanic'), 3);       // dvd: 3 dias
  assert.equal(biblioteca.emprestar('Disco Vinil'), 7);   // mídia comum: 7 dias
});

test('composição: acervo controla disponíveis e emprestadas', () => {
  const biblioteca = new Biblioteca();
  biblioteca.adicionarMidia(new Livro('Iracema', 1865, 'José de Alencar', 200));
  biblioteca.adicionarMidia(new DVD('O Poderoso Chefão', 1972, 'Francis Ford Coppola', 175));
  assert.deepEqual(biblioteca.disponiveis(), [
    'Livro: Iracema (1865) — José de Alencar, 200 páginas',
    'DVD: O Poderoso Chefão (1972) — Francis Ford Coppola, 175 min',
  ]);
  biblioteca.emprestar('Iracema');
  assert.deepEqual(biblioteca.disponiveis(), [
    'DVD: O Poderoso Chefão (1972) — Francis Ford Coppola, 175 min',
  ]);
  assert.deepEqual(biblioteca.emprestadas(), [
    'Livro: Iracema (1865) — José de Alencar, 200 páginas',
  ]);
  biblioteca.devolver('Iracema');
  assert.equal(biblioteca.disponiveis().length, 2);
  assert.equal(biblioteca.emprestadas().length, 0);
});

test('regras e erros: validações das classes e do serviço', () => {
  const biblioteca = new Biblioteca();
  assert.throws(() => biblioteca.adicionarMidia({ titulo: 'Não sou mídia' }));
  assert.throws(() => new Livro('', 1890, 'Autor', 100));
  assert.throws(() => new DVD('Filme', '1999', 'Diretor', 90));
  biblioteca.adicionarMidia(new Livro('Memórias Póstumas', 1881, 'Machado de Assis', 208));
  assert.throws(() => biblioteca.emprestar('Livro Inexistente'));
  assert.equal(biblioteca.emprestar('Memórias Póstumas'), 14);
  assert.throws(() => biblioteca.emprestar('Memórias Póstumas')); // já emprestada
  assert.equal(biblioteca.emprestadas().length, 1);
  biblioteca.devolver('Memórias Póstumas');
  assert.throws(() => biblioteca.devolver('Memórias Póstumas')); // já devolvida
});
